type actorClient struct {
	baseURL string
	http    *http.Client
	token   string
	userID  string
}

type flowEnv struct {
	alpha   *actorClient
	beta    *actorClient
	manager *actorClient
}

func newFlowEnv(t *testing.T) *flowEnv {
	t.Helper()
	baseURL := strings.TrimRight(os.Getenv("DOMAINRY_BF_BASE_URL"), "/")
	password := os.Getenv("DOMAINRY_BF_PASSWORD")
	if baseURL == "" || password == "" {
		t.Skip("real Runtime business-flow environment is not configured")
	}
	return &flowEnv{
		alpha:   loginActor(t, baseURL, "agent_alpha", password),
		beta:    loginActor(t, baseURL, "agent_beta", password),
		manager: loginActor(t, baseURL, "manager_main", password),
	}
}

func loginActor(t *testing.T, baseURL, userID, password string) *actorClient {
	t.Helper()
	client := &actorClient{baseURL: baseURL, userID: userID}
	workspaceCandidates := []string{os.Getenv("DOMAINRY_BF_WORKSPACE_ID")}
	if workspaceCandidates[0] == "" {
		workspaceCandidates = []string{"default", "internal_ticketing"}
	}
	changedPassword := password + "-" + userID + "-changed"
	passwordCandidates := []string{changedPassword, password}
	var lastStatus int
	var lastBody []byte
	for _, workspaceID := range workspaceCandidates {
		for _, candidatePassword := range passwordCandidates {
			jar, err := cookiejar.New(nil)
			if err != nil {
				t.Fatalf("create cookie jar: %v", err)
			}
			client.http = &http.Client{Jar: jar, Timeout: 15 * time.Second}
			client.token = ""
			status, body := client.request(t, http.MethodPost, "/auth/login", map[string]any{
				"workspace_id": workspaceID,
				"login":        userID,
				"password":     candidatePassword,
			}, "")
			lastStatus, lastBody = status, body
			if status < 200 || status >= 300 {
				continue
			}
			var payload any
			if len(body) > 0 {
				if err := json.Unmarshal(body, &payload); err != nil {
					t.Fatalf("decode login response for %s: %v", userID, err)
				}
				client.token = findStringKey(payload, "access_token", "token", "bearer_token")
			}
			meStatus, meBody := client.request(t, http.MethodGet, "/auth/me", nil, "")
			if meStatus != http.StatusOK {
				t.Fatalf("authenticated session probe for %s failed: status=%d body=%s", userID, meStatus, boundedBody(meBody))
			}
			if !bytes.Contains(meBody, []byte(userID)) {
				t.Fatalf("authenticated session identity mismatch for %s: %s", userID, boundedBody(meBody))
			}
			menuStatus, menuBody := client.request(t, http.MethodGet, "/identity/effective-menus?surface="+businessSurface, nil, "")
			if menuStatus == http.StatusOK {
				return client
			}
			if candidatePassword == changedPassword || !strings.Contains(strings.ToLower(string(menuBody)), "password_change_required") {
				lastStatus, lastBody = menuStatus, menuBody
				continue
			}
			changePassword(t, client, candidatePassword, changedPassword)
			return loginActor(t, baseURL, userID, password)
		}
	}
	t.Fatalf("login failed for non-human identity %s: status=%d body=%s", userID, lastStatus, boundedBody(lastBody))
	return nil
}

func changePassword(t *testing.T, client *actorClient, currentPassword, newPassword string) {
	t.Helper()
	requests := []map[string]any{
		{"current_password": currentPassword, "new_password": newPassword},
		{"old_password": currentPassword, "new_password": newPassword},
		{"password": currentPassword, "new_password": newPassword},
		{"currentPassword": currentPassword, "newPassword": newPassword},
	}
	var lastStatus int
	var lastBody []byte
	for index, request := range requests {
		status, body := client.request(t, http.MethodPost, "/auth/change-password", request, fmt.Sprintf("first-login-%s-%d", client.userID, index))
		lastStatus, lastBody = status, body
		if status >= 200 && status < 300 {
			return
		}
	}
	t.Fatalf("first-login password change failed for %s: status=%d body=%s", client.userID, lastStatus, boundedBody(lastBody))
}

func (c *actorClient) request(t *testing.T, method, path string, body any, idempotencyKey string) (int, []byte) {
	t.Helper()
	var reader io.Reader
	if body != nil {
		encoded, err := json.Marshal(body)
		if err != nil {
			t.Fatalf("encode request body: %v", err)
		}
		reader = bytes.NewReader(encoded)
	}
	req, err := http.NewRequestWithContext(t.Context(), method, c.baseURL+path, reader)
	if err != nil {
		t.Fatalf("construct %s %s: %v", method, path, err)
	}
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if c.token != "" {
		req.Header.Set("Authorization", "Bearer "+c.token)
	}
	if idempotencyKey != "" {
		req.Header.Set("Idempotency-Key", idempotencyKey)
	}
	resp, err := c.http.Do(req)
	if err != nil {
		t.Fatalf("execute %s %s: %v", method, path, err)
	}
	defer resp.Body.Close()
	responseBody, err := io.ReadAll(io.LimitReader(resp.Body, 2<<20))
	if err != nil {
		t.Fatalf("read %s %s response: %v", method, path, err)
	}
	return resp.StatusCode, responseBody
}

func (c *actorClient) mustJSON(t *testing.T, method, path string, body any, idempotencyKey string) any {
	t.Helper()
	status, responseBody := c.request(t, method, path, body, idempotencyKey)
	if status < 200 || status >= 300 {
		t.Fatalf("%s %s failed: status=%d body=%s", method, path, status, boundedBody(responseBody))
	}
	if len(responseBody) == 0 {
		return map[string]any{}
	}
	var payload any
	if err := json.Unmarshal(responseBody, &payload); err != nil {
		t.Fatalf("decode %s %s response: %v body=%s", method, path, err, boundedBody(responseBody))
	}
	return payload
}

func (c *actorClient) mustReject(t *testing.T, method, path string, body any, idempotencyKey string, categories ...string) []byte {
	t.Helper()
	status, responseBody := c.request(t, method, path, body, idempotencyKey)
	if status >= 200 && status < 300 {
		t.Fatalf("%s %s unexpectedly succeeded: %s", method, path, boundedBody(responseBody))
	}
	text := strings.ToLower(string(responseBody))
	for _, category := range categories {
		if strings.Contains(text, strings.ToLower(category)) {
			return responseBody
		}
	}
	if len(categories) > 0 {
		t.Fatalf("%s %s rejected for wrong reason: status=%d expected=%v body=%s", method, path, status, categories, boundedBody(responseBody))
	}
	return responseBody
}

