	const assignKey = "bf02-highest-risk-canary-assign-v1"
	ticketID := createTicket(t, env.alpha, createKey, "BF02 Highest Risk Canary", "urgent")
	if replayID := createTicket(t, env.alpha, createKey, "BF02 Highest Risk Canary", "urgent"); replayID != ticketID {
		t.Fatalf("canary create replay changed identity: first=%s replay=%s", ticketID, replayID)
	}
	betaProfileID := profileIDByName(t, env.manager, "Agent Beta")
	payload := env.manager.runRecordAction(t, ticketID, "ticket.assign_ticket", map[string]any{
		"request_id": assignKey, "assignee_id": betaProfileID,
	}, assignKey)
	if findStringKey(payload, "notification_receipt_id") == "" {
		t.Fatalf("assignment returned no notification receipt: %#v", payload)
	}
	if got := stringField(env.manager.getRecord(t, "ticket", ticketID).Data, "assignee_id"); got != betaProfileID {
		t.Fatalf("canary durable assignee mismatch: got=%s want=%s", got, betaProfileID)
	}
	if count := notificationCountForTicket(t, env.beta, ticketID); count != 1 {
		t.Fatalf("canary recipient Inbox count=%d, want exactly 1", count)
	}
	if count := notificationCountForTicket(t, env.alpha, ticketID); count != 0 {
