func flowBF01(t *testing.T, env *flowEnv) {
	key := nonce("bf01-create")
	title := "BF01 " + key
	ticketID := createTicket(t, env.alpha, key, title, "high")
	if replayID := createTicket(t, env.alpha, key, title, "high"); replayID != ticketID {
		t.Fatalf("idempotent replay changed identity: first=%s replay=%s", ticketID, replayID)
	}
	record := env.manager.getRecord(t, "ticket", ticketID)
	if stringField(record.Data, "status") != "new" || stringField(record.Data, "priority") != "high" || stringField(record.Data, "title") != title {
		t.Fatalf("created ticket fields mismatch: %+v", record.Data)
	}
	beforeCount := countRecords(t, env.manager, "ticket", func(item runtimeRecord) bool { return stringField(item.Data, "title") == title })
	if beforeCount != 1 {
		t.Fatalf("idempotent create produced %d rows, want 1", beforeCount)
	}
	env.alpha.mustReject(t, http.MethodPost, "/objects/ticket/actions/ticket.create_ticket/run", map[string]any{"data": map[string]any{
		"request_id": key, "title": title + " mismatch", "priority": "high", "reporter_name": "Reporter",
	}}, key, "idempotency", "conflict")
	afterCount := countRecords(t, env.manager, "ticket", func(item runtimeRecord) bool { return strings.HasPrefix(stringField(item.Data, "title"), title) })
	if afterCount != 1 {
		t.Fatalf("mismatched replay changed durable row count: before=1 after=%d", afterCount)
	}
}

func flowBF02(t *testing.T, env *flowEnv) {
	createKey := nonce("bf02-create")
	ticketID := createTicket(t, env.alpha, createKey, "BF02 "+createKey, "urgent")
	betaProfileID := profileIDByName(t, env.manager, "Agent Beta")
	beforeBeta := notificationCountForTicket(t, env.beta, ticketID)
	beforeAlpha := notificationCountForTicket(t, env.alpha, ticketID)
	assignKey := nonce("bf02-assign")
	payload := env.manager.runRecordAction(t, ticketID, "ticket.assign_ticket", map[string]any{
		"request_id": assignKey, "assignee_id": betaProfileID,
	}, assignKey)
	if findStringKey(payload, "notification_receipt_id") == "" {
		t.Fatalf("assignment returned empty notification receipt: %#v", payload)
	}
	if got := stringField(env.manager.getRecord(t, "ticket", ticketID).Data, "assignee_id"); got != betaProfileID {
		t.Fatalf("durable assignment mismatch: got=%s want=%s", got, betaProfileID)
	}
	if got := notificationCountForTicket(t, env.beta, ticketID); got != beforeBeta+1 {
		t.Fatalf("recipient Inbox delta=%d, want 1", got-beforeBeta)
	}
	if got := notificationCountForTicket(t, env.alpha, ticketID); got != beforeAlpha {
		t.Fatalf("notification leaked to old assignee: before=%d after=%d", beforeAlpha, got)
	}
	before := env.manager.getRecord(t, "ticket", ticketID)
	env.alpha.rejectRecordAction(t, ticketID, "ticket.assign_ticket", map[string]any{"request_id": nonce("denied-assign"), "assignee_id": betaProfileID}, nonce("denied-header"), "permission_denied")
	after := env.manager.getRecord(t, "ticket", ticketID)
	if stringField(after.Data, "assignee_id") != stringField(before.Data, "assignee_id") || notificationCountForTicket(t, env.beta, ticketID) != beforeBeta+1 {
		t.Fatal("denied assignment changed ticket or Inbox state")
	}
}

